import { useState } from 'react';
import ApprovalDialog from '../../components/ApprovalDialog';
import StatusBadge from '../../components/StatusBadge';
import { useApprovalDecision } from '../../hooks/useCommand';
import { useOnyxQuery } from '../../hooks/useQuery';
import type { ApprovalProjection } from '../../types/query';

export default function ApprovalsPage() { const query = useOnyxQuery<ApprovalProjection>('approval.list'); const mutation = useApprovalDecision(); const [dialog, setDialog] = useState<{ approval: ApprovalProjection; decision: 'approve' | 'reject' } | null>(null); const confirm = (reason: string) => { if (!dialog) return; mutation.mutate({ ...dialog, reason }, { onSuccess: () => setDialog(null) }); }; return <div className="page-stack"><header className="page-header"><div><p className="eyebrow">Authority workflow</p><h1>Approvals</h1><p>Decisions are pinned to the displayed target version and epochs.</p></div></header><div className="card-list">{query.data?.data.map((approval) => <article className="approval-card" key={approval.id}><div className="approval-main"><div className="card-title-row"><h2>{approval.title}</h2><StatusBadge status={approval.status} /></div><p>{approval.description}</p><dl className="inline-details"><div><dt>Requested by</dt><dd>{approval.requested_by}</dd></div><div><dt>Target</dt><dd>{approval.target_type}</dd></div><div><dt>Version</dt><dd>{approval.version}</dd></div></dl></div>{approval.status === 'pending' && approval.web_action_permitted ? <div className="approval-actions"><button className="button-secondary" onClick={() => setDialog({ approval, decision: 'reject' })}>Reject</button><button className="button-primary" onClick={() => setDialog({ approval, decision: 'approve' })}>Approve</button></div> : approval.status === 'pending' ? <div className="restricted-action"><strong>Native client required</strong><span>Web-based decision is not permitted by policy.</span></div> : null}</article>)}</div>{dialog ? <ApprovalDialog {...dialog} busy={mutation.isPending} onCancel={() => setDialog(null)} onConfirm={confirm} /> : null}</div>; }
